import { operation } from "@tinker/core";

import { drizzleOrm } from "~/components/database/index.server";
import { database } from "~/components/database/index.server";
import { readTodoCommand } from "~/components/demo/contracts/commands";
import type { Sync } from "~/components/demo/contracts/sync";
import type { Todos } from "~/components/demo/contracts/todos-contract";
import { raise } from "~/components/demo/errors";
import { eventHistory, execution } from "~/components/sync/index.server";

import { currentUser } from "./auth.server";
import { todo } from "./todos.schema.server";

export const listTodos = operation({
  label: "listTodos",
  depends: { orm: drizzleOrm, currentUser, database },
  run: ({ orm, currentUser, database }): Promise<Todos.Row[]> => {
    const { asc, eq } = orm;
    return database
      .select({ id: todo.id, title: todo.title, done: todo.done })
      .from(todo)
      .where(eq(todo.ownerId, currentUser.id))
      .orderBy(asc(todo.id));
  },
});

export const changeTodo = operation({
  label: "changeTodo",
  input: readTodoCommand,
  depends: { orm: drizzleOrm, currentUser, database, history: eventHistory },
  run: async ({ orm, currentUser, database, history }, { input }) => {
    const { and, asc, eq } = orm;

    await database.transaction(async (tx) => {
      await history.lock(tx, currentUser.id);
      if (await history.find(tx, input.executionId, currentUser.id)) return;

      const change = input.change;
      let changed = true;
      if (change.kind === "add") {
        await tx.insert(todo).values({ ownerId: currentUser.id, title: change.title });
      } else {
        const owned = and(eq(todo.id, change.id), eq(todo.ownerId, currentUser.id));
        const row = (await tx.select().from(todo).where(owned)).at(0);
        if (!row) raise("TodoMissing", {});
        if (change.kind === "delete") await tx.delete(todo).where(owned);
        else if (row.done !== change.done) {
          await tx.update(todo).set({ done: change.done }).where(owned);
        } else changed = false;
      }

      await tx.insert(execution).values({ id: input.executionId, stream: currentUser.id });

      const payloads: Sync.Payload[] = [];
      if (changed) {
        const rows = await tx
          .select({ id: todo.id, title: todo.title, done: todo.done })
          .from(todo)
          .where(eq(todo.ownerId, currentUser.id))
          .orderBy(asc(todo.id));
        payloads.push({ kind: "change", change: { kind: "todos", rows } });
      }

      payloads.push({ kind: "result", result: { kind: "complete", action: "todo" } });
      await history.append(tx, currentUser.id, input.executionId, payloads);
    });

    return { executionId: input.executionId };
  },
});

import { pgTable, integer, text, boolean, index } from "drizzle-orm/pg-core";

import { user } from "~/components/auth/index.server";

export const todo = pgTable(
  "todo",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    ownerId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text().notNull(),
    done: boolean().notNull().default(false),
  },
  (table) => [index("todo_owner_id").on(table.ownerId)],
);

import { z } from "zod";

import { raise } from "~/components/demo/errors";

export declare namespace Todos {
  type Row = { id: number; title: string; done: boolean };
  type Change = z.infer<typeof todoChange>;
}

const todoChange = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("add"), title: z.string().trim().min(1).max(200) }).strict(),
  z
    .object({
      kind: z.literal("setDone"),
      id: z.number().int().positive().max(2_147_483_647),
      done: z.boolean(),
    })
    .strict(),
  z
    .object({ kind: z.literal("delete"), id: z.number().int().positive().max(2_147_483_647) })
    .strict(),
]);

/** The schema keeps the same managed refusal at each input door. */
export const readTodoChange = todoChange.catch(() =>
  raise("BadInput", { reason: "Use a title with 1 to 200 characters and a valid todo change." }),
);

import { z } from "zod";
import { data, operation, isError as isCoreError } from "@tinker/core";
import { useData, useRun } from "@tinker/react";
import { Link, Navigate, useRouterState } from "@tanstack/react-router";
import { updateTodo } from "@/transport/todos.functions";
import { readTodoChange } from "~/components/demo";
import { todos, profile } from "~/components/demo";
import { syncClient } from "@tinker/start/client";
import { isError } from "~/components/demo";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "./ui/card";
const flow = data<{ kind: "idle" } | { kind: "saving" } | { kind: "failed"; message: string }>({
  label: "todos.flow",
  initial: { kind: "idle" },
});
const saveTodo = operation({
  label: "todos.save",
  input: readTodoChange,
  depends: { flow: flow.controller, sync: syncClient },
  run: async ({ flow, sync }, { defer, random, input, signal }) => {
    flow.set({ kind: "saving" });
    defer(() => flow.set({ kind: "idle" }));
    const executionId = random.uuid();
    await sync.execute(
      executionId,
      { send: updateTodo, data: { executionId, change: input } },
      signal,
    );
  },
});
const showFailure = operation({
  label: "todos.showFailure",
  input(error: unknown) {
    const cause = isCoreError(error, "DataValidationFailed") ? error.payload.cause : error;
    return isError(cause, "BadInput")
      ? cause.payload.reason
      : "That change did not finish. Try again or reload the page.";
  },
  depends: { flow: flow.controller },
  run: ({ flow }, { input }) => {
    flow.set({
      kind: "failed",
      message: input,
    });
  },
});
const attemptTodo = operation({
  label: "todos.attempt",
  input: z.unknown(),
  depends: { save: saveTodo, failure: showFailure },
  run: async ({ save, failure }, { input }) => {
    const result = await save.settle({ rawInput: input });
    if (result.status === "success") return true;
    if (result.status === "failed") failure.run({ rawInput: result.error });
    else failure.run({ rawInput: undefined });
    return false;
  },
});
export function Todos() {
  const rows = useData(todos);
  const account = useData(profile);
  const loading = useRouterState({ select: (state) => state.isLoading });
  const state = useData(flow);
  const save = useRun(attemptTodo);
  const busy = state.kind === "saving" || loading;
  if (account === null) return <Navigate to="/demo" />;
  return (
    <main className="mx-auto max-w-2xl px-5 py-8 sm:py-12">
      <header className="mb-8 flex items-center justify-between gap-4">
        <div>
          <p className="text-xs font-semibold tracking-widest text-muted-foreground">
            TINKERED / TODOS
          </p>
          <p className="mt-2 break-all text-sm text-muted-foreground">
            {account.name} · {account.email}
          </p>
        </div>
        <Button asChild variant="outline">
          <Link to="/profile" disabled={busy}>
            Account
          </Link>
        </Button>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>
            <h1>Your private list</h1>
          </CardTitle>
          <CardDescription>Only you can read or change these todos.</CardDescription>
        </CardHeader>
        <CardContent>
          <form
            className="mb-5 flex items-end gap-2"
            onSubmit={async (event) => {
              event.preventDefault();
              const form = event.currentTarget;
              if (
                await save.runAsync({
                  rawInput: { kind: "add", title: new FormData(form).get("title") },
                })
              )
                form.reset();
            }}
          >
            <label className="grid min-w-0 flex-1 gap-2 text-sm font-medium">
              New todo
              <Input
                name="title"
                placeholder="What needs doing?"
                required
                maxLength={200}
                disabled={busy}
              />
            </label>
            <Button disabled={busy}>Add todo</Button>
          </form>
          <p role="alert" className="mb-3 text-sm text-destructive">
            {state.kind === "failed" ? state.message : null}
          </p>
          {rows.length === 0 ? (
            <p className="rounded-lg border border-dashed p-6 text-center text-sm text-muted-foreground">
              Your list is empty. Add your first todo.
            </p>
          ) : (
            <ul className="divide-y">
              {rows.map((row) => (
                <li key={row.id} className="flex items-center gap-3 py-3">
                  <label className="flex min-w-0 flex-1 items-center gap-3 text-sm">
                    <input
                      type="checkbox"
                      checked={row.done}
                      disabled={busy}
                      onChange={(event) =>
                        save.runAsync({
                          rawInput: { kind: "setDone", id: row.id, done: event.target.checked },
                        })
                      }
                      className="size-4 shrink-0 accent-primary"
                    />
                    <span
                      className={
                        row.done
                          ? "min-w-0 break-words text-muted-foreground line-through"
                          : "min-w-0 break-words"
                      }
                    >
                      {row.title}
                    </span>
                  </label>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    disabled={busy}
                    aria-label={`Delete ${row.title}`}
                    onClick={() => save.runAsync({ rawInput: { kind: "delete", id: row.id } })}
                  >
                    Delete
                  </Button>
                </li>
              ))}
            </ul>
          )}
          <p className="mt-5 text-xs text-muted-foreground">
            {rows.filter((row) => row.done).length} of {rows.length} done. Changes are saved in your
            account.
          </p>
        </CardContent>
      </Card>
    </main>
  );
}

import { createFileRoute, redirect } from "@tanstack/react-router";
import { Todos } from "@/frontend/Todos";
export const Route = createFileRoute("/todos")({
  gcTime: 0,
  beforeLoad: async ({ context }) => {
    if ((await context.account()) === null) throw redirect({ to: "/demo" });
    await context.bootstrap();
  },
  component: Todos,
});

import { createServerFn } from "@tanstack/react-start";
import { setResponseHeader } from "@tanstack/react-start/server";

import { readTodoCommand } from "~/components/demo";
import { listTodos, changeTodo } from "~/components/demo/index.server";
import { startRequests } from "~/components/requests";
import { readResult } from "~/components/requests/index.server";

import { readReceipt } from "./result.server";

export const getTodos = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) => {
    setResponseHeader("Cache-Control", "no-store");
    return readResult(await context.session.settle(listTodos, { signal: context.signal }));
  });

export const updateTodo = createServerFn({ method: "POST" })
  .middleware([startRequests.middleware])
  .validator(readTodoCommand)
  .handler(async ({ context, data }) =>
    readReceipt(await context.session.settle(changeTodo, { input: data, signal: context.signal })),
  );

import { operation, resource } from "@tinker/core";

import { user } from "~/components/auth/index.server";
import { principal } from "~/components/auth/index.server";
import { drizzleOrm } from "~/components/database/index.server";
import { database } from "~/components/database/index.server";
import { readProfileCommand } from "~/components/demo/contracts/commands";
import type { Profile } from "~/components/demo/contracts/profile-contract";
import { readExecution, readRetry, readFeatureResult } from "~/components/demo/contracts/sync";
import type { Sync } from "~/components/demo/contracts/sync";
import { raise } from "~/components/demo/errors";
import { sendMail } from "~/components/mail/index.server";
import { eventHistory, execution } from "~/components/sync/index.server";

import { currentUser } from "./auth.server";

export const readProfile = operation({
  label: "readProfile",
  depends: { orm: drizzleOrm, principal, database },
  run: async ({ orm, principal, database }): Promise<Profile.Value | null> => {
    const { eq } = orm;
    if (principal === null) return null;
    return (
      (
        await database
          .select({
            id: user.id,
            name: user.name,
            email: user.email,
            emailVerified: user.emailVerified,
          })
          .from(user)
          .where(eq(user.id, principal.id))
      ).at(0) ?? null
    );
  },
});

/** Mail runs after commit and outside a database lock; only its final event needs a transaction. */
const notifyProfile = operation({
  label: "notifyProfile",
  input: readExecution,
  depends: { orm: drizzleOrm, database, history: eventHistory, send: sendMail },
  run: async ({ orm, database, history, send }, { input }) => {
    const { eq } = orm;
    const stored = (
      await database.select().from(execution).where(eq(execution.id, input.executionId))
    ).at(0);
    if (!stored?.notification) raise("RetryNotAvailable", {});
    if (stored.result) return { executionId: input.executionId };

    const sent = await send.settle({ rawInput: stored.notification });
    const result: Sync.Result =
      sent.status === "success"
        ? { kind: "complete", action: "profile", profileId: stored.stream }
        : {
            kind: "partial",
            action: "profile",
            profileId: stored.stream,
            notification: {
              kind: "failed",
              message: "Name saved; notification failed. You can retry the notification.",
            },
          };

    await database.transaction(async (tx) => {
      await history.lock(tx, stored.stream);
      const latest = await history.find(tx, input.executionId, stored.stream);
      if (latest?.result) return;
      await history.append(tx, stored.stream, input.executionId, [{ kind: "result", result }]);
    });

    return { executionId: input.executionId };
  },
});

/** One process owner coalesces duplicate requests; this is not a cross-process SMTP guarantee. */
const notificationWork = resource({
  label: "profile.notificationWork",
  depends: { finish: notifyProfile },
  factory: ({ finish }, { log, defer }) => {
    const running = new Map<string, Promise<void>>();
    defer(async () => {
      await Promise.all(running.values());
    });
    return {
      finish(executionId: string) {
        if (running.has(executionId)) return;
        const completed = finish.settle({ input: { executionId } }).then((result) => {
          running.delete(executionId);
          if (result.status !== "success") {
            log.error("profile.notification.failed", { executionId, status: result.status });
          }
        });
        running.set(executionId, completed);
      },
    };
  },
});

export const saveProfile = operation({
  label: "saveProfile",
  input: readProfileCommand,
  depends: {
    orm: drizzleOrm,
    currentUser,
    database,
    history: eventHistory,
    notify: notificationWork,
  },
  run: async ({ orm, currentUser, database, history, notify }, { input, clock }) => {
    const { eq } = orm;

    await database.transaction(async (tx) => {
      await history.lock(tx, currentUser.id);
      if (await history.find(tx, input.executionId, currentUser.id)) return;

      const saved = (
        await tx
          .update(user)
          .set({ name: input.profile.name, updatedAt: new Date(clock.currentTimeMillis()) })
          .where(eq(user.id, currentUser.id))
          .returning({
            id: user.id,
            name: user.name,
            email: user.email,
            emailVerified: user.emailVerified,
          })
      ).at(0);
      if (!saved) raise("SignInRequired", {});

      await tx.insert(execution).values({
        id: input.executionId,
        stream: currentUser.id,
        notification: {
          to: saved.email,
          subject: "Your profile was updated",
          text: `Your saved name is ${saved.name}.`,
        },
      });

      await history.append(tx, currentUser.id, input.executionId, [
        { kind: "change", change: { kind: "profile", profile: saved } },
      ]);
    });

    notify.finish(input.executionId);
    return { executionId: input.executionId };
  },
});

export const retryNotification = operation({
  label: "retryNotification",
  input: readRetry,
  depends: {
    currentUser,
    database,
    history: eventHistory,
    notify: notificationWork,
  },
  run: async ({ currentUser, database, history, notify }, { input }) => {
    await database.transaction(async (tx) => {
      await history.lock(tx, currentUser.id);
      if (await history.find(tx, input.executionId, currentUser.id)) return;

      const previous = await history.find(tx, input.previousExecutionId, currentUser.id);
      if (!previous?.notification || !previous.result) raise("RetryNotAvailable", {});
      const result = readFeatureResult.safeParse(previous.result);
      if (!result.success || result.data.kind !== "partial") raise("RetryNotAvailable", {});

      await tx.insert(execution).values({
        id: input.executionId,
        stream: currentUser.id,
        notification: previous.notification,
      });
    });

    notify.finish(input.executionId);
    return { executionId: input.executionId };
  },
});

import { z } from "zod";

import { raise } from "~/components/demo/errors";

export declare namespace Profile {
  type Value = { id: string; name: string; email: string; emailVerified: boolean };
  type Input = { name: string };
}

const profileInput = z.object({ name: z.string().trim().min(1).max(80) }).strict();

/** The schema keeps the same managed refusal at each input door. */
export const readProfileInput = profileInput.catch(() =>
  raise("BadInput", { reason: "Use a name with 1 to 80 letters." }),
);

import { Link, Navigate } from "@tanstack/react-router";
import { useData, useRun } from "@tinker/react";
import type { Profile } from "~/components/demo";
import { profile, nameDraft, pending, notice, profileResult } from "~/components/demo";
import { signOut } from "./auth-actions";
import { saveName, editName, retryMail } from "./profile-actions";
import { errorText } from "./error-text";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "./ui/card";
function ProfileForm({ value }: { value: Profile.Value }) {
  const draft = useData(nameDraft);
  const last = useData(profileResult);
  const retry = useRun(retryMail);
  const changeName = useRun(editName);
  const save = useRun(saveName);
  const leave = useRun(signOut);
  const busy = useData(pending);
  return (
    <form
      className="space-y-5"
      onSubmit={(event) => {
        event.preventDefault();
        save.run({ rawInput: { name: draft ?? value.name } });
      }}
    >
      <div className="flex min-w-0 items-center gap-3 rounded-lg bg-muted p-3">
        <span className="grid size-10 shrink-0 place-items-center rounded-full bg-accent font-semibold">
          {value.name.slice(0, 1).toUpperCase()}
        </span>
        <div className="min-w-0">
          <strong className="block truncate text-sm">{value.name}</strong>
          <small className="block truncate text-muted-foreground">{value.email}</small>
        </div>
        <span className="ml-auto shrink-0 text-xs text-muted-foreground">Signed in</span>
      </div>
      <label className="grid gap-2 text-sm font-medium">
        Name
        <Input
          value={draft ?? value.name}
          disabled={busy}
          onChange={(event) => changeName.run({ input: event.target.value })}
          required
          maxLength={80}
        />
      </label>
      <div className="flex gap-2">
        <Button disabled={busy}>{save.status === "pending" ? "Saving…" : "Save name"}</Button>
        <Button
          type="button"
          variant="outline"
          disabled={leave.status === "pending"}
          onClick={() => leave.run()}
        >
          {leave.status === "pending" ? "Signing out…" : "Sign out"}
        </Button>
      </div>
      {last?.result.kind === "partial" && (
        <Button
          type="button"
          variant="secondary"
          disabled={busy}
          onClick={() => retry.run({ input: last.executionId })}
        >
          Retry notification
        </Button>
      )}
      <Button asChild variant="secondary">
        <Link to="/todos" disabled={busy}>
          Open my todos
        </Link>
      </Button>
      <p role="alert" className="text-sm text-destructive">
        {errorText(save.error || leave.error)}
      </p>
    </form>
  );
}
export function ProfilePage() {
  const current = useData(profile);
  const message = useData(notice);
  if (current === null) return <Navigate to="/demo" />;
  return (
    <main className="mx-auto max-w-2xl space-y-6 px-5 py-8">
      <Link to="/demo" className="text-sm underline">
        Shared counter
      </Link>
      <Card>
        <CardHeader>
          <CardTitle>
            <h1>Your profile</h1>
          </CardTitle>
          <CardDescription>
            Your saved name is shared with your private list. Unsaved text stays in this editor.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <ProfileForm value={current} />
          <p role="status" className="mt-3 text-sm">
            {message}
          </p>
        </CardContent>
      </Card>
    </main>
  );
}

import { operation } from "@tinker/core";
import { z } from "zod";

import { readProfileInput } from "~/components/demo";
import { raise } from "~/components/demo";
import { nameDraft, pending, notice, profileResult } from "~/components/demo";
import { syncClient } from "~/components/sync";

import { updateProfile, retryProfileNotification } from "@/transport/profile.functions";

const notificationId = z.uuid();
const draftInput = z.string();

export const saveName = operation({
  label: "saveName",
  input: readProfileInput,
  depends: {
    sync: syncClient,
    draft: nameDraft.controller,
    pending: pending.controller,
    notice: notice.controller,
    result: profileResult.controller,
  },
  run: async ({ sync, draft, pending, notice, result }, { defer, random, input, signal }) => {
    pending.set(true);
    notice.set("");
    defer(() => pending.set(false));

    const executionId = random.uuid();
    const completed = await sync.execute(
      executionId,
      { send: updateProfile, data: { executionId, profile: input } },
      signal,
    );

    result.set({ executionId, result: completed });
    if (completed.kind === "failed") raise("WriteRejected", { message: completed.message });

    draft.set(undefined);
    notice.set(
      completed.kind === "partial"
        ? completed.notification.message
        : "Name saved and notification accepted.",
    );
  },
});

export const retryMail = operation({
  label: "retryMail",
  input: (raw: unknown) => notificationId.parse(raw),
  depends: {
    sync: syncClient,
    pending: pending.controller,
    notice: notice.controller,
    result: profileResult.controller,
  },
  run: async ({ sync, pending, notice, result }, { defer, random, input, signal }) => {
    pending.set(true);
    defer(() => pending.set(false));

    const executionId = random.uuid();
    const completed = await sync.execute(
      executionId,
      { send: retryProfileNotification, data: { executionId, previousExecutionId: input } },
      signal,
    );

    result.set({ executionId, result: completed });
    notice.set(
      completed.kind === "complete"
        ? "Notification accepted. Your saved name stayed the same."
        : completed.kind === "partial"
          ? completed.notification.message
          : completed.message,
    );
  },
});

export const editName = operation({
  label: "editName",
  input: (raw: unknown) => draftInput.parse(raw),
  depends: { draft: nameDraft.controller },
  run: ({ draft }, { input }) => draft.set(input),
});

import { createFileRoute, redirect } from "@tanstack/react-router";
import { ProfilePage } from "@/frontend/Profile";
export const Route = createFileRoute("/profile")({
  gcTime: 0,
  beforeLoad: async ({ context }) => {
    if ((await context.account()) === null) throw redirect({ to: "/demo" });
    await context.bootstrap();
  },
  component: ProfilePage,
});

import { createServerFn } from "@tanstack/react-start";

import { readProfileCommand } from "~/components/demo";
import { readRetry } from "~/components/demo";
import { readProfile, saveProfile, retryNotification } from "~/components/demo/index.server";
import { startRequests } from "~/components/requests";
import { readResult } from "~/components/requests/index.server";

import { readReceipt } from "./result.server";

export const getProfile = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) =>
    readResult(await context.session.settle(readProfile, { signal: context.signal })),
  );

export const updateProfile = createServerFn({ method: "POST" })
  .middleware([startRequests.middleware])
  .validator(readProfileCommand)
  .handler(async ({ context, data }) =>
    readReceipt(await context.session.settle(saveProfile, { input: data, signal: context.signal })),
